function getValueFromDotNotation(obj, keys) {
    if (!keys || !obj) {
        throw new Error("Invalid input: 'obj' must be an object and 'keys' array should not be empty.");
    }

    // Helper function to perform DFS
    const dfs = (currentObj, remainingKeys) => {
        for (let key of remainingKeys) {
            if (typeof currentObj !== "object" || currentObj === null) {
                throw new Error(`Key '${key}' does not exist.`);
            }

            if (Array.isArray(currentObj)) {
                // Check each item in the array
                currentObj.forEach(item => {
                    dfs(item, [...remainingKeys].slice(0));
                });
            } else {
                // Check if the property exists
